mapper.select:
SELECT oralTariffCategoryId, oraltariffCategoryName, oraltariffCategoryNumber, oraltariffId, `name`, price, englishName, number, unit, inservice FROM ( SELECT botc.id AS oralTariffCategoryId, botc.`name` AS oraltariffCategoryName, botc.number AS oraltariffCategoryNumber, bot.id AS oraltariffId, bot.`name`, IFNULL( cot.price, bot.price ) AS price, bot.english_name AS englishName, bot.item_number AS number, bot.unit, IFNULL( cot.inservice, 1 ) AS inservice FROM base_oral_tariff bot LEFT JOIN base_oral_tariff_category botc ON bot.oral_tariff_category_id = botc.id LEFT JOIN ( SELECT cot.clinic_id, cot.oral_tariff_id, cot.price, cot.inservice FROM clinic_oral_tariff cot
and cot.clinic_id = #{queryForm.orgId}
) cot ON bot.id = cot.oral_tariff_id ) cot
and cot.oralTariffCategoryId = #{queryForm.oralTariffCategoryId}
and CONCAT(IFNULL( cot.name, '' ), IFNULL( cot.pinyin, '' ), IFNULL( cot.number, '' )) like concat('%', #{queryForm.keyWord}, '%')
and cot.inservice = #{queryForm.inservice}

select cot.id, cot.oralTariffCategoryId, cot.oralTariffCategoryName, cot.oralTariffCategoryNumber, cot.`number` as itemNumber, cot.`name`, cot.pinyin, cot.englishName, cot.unit, cot.price, cot.inservice from ( select cot.id, cot.clinic_id as orgId, botbotc.oralTariffCategoryId, botbotc.oralTariffCategoryName, botbotc.oralTariffCategoryNumber, botbotc.oralTariffId, botbotc.`name`, botbotc.pinyin, botbotc.englishName, botbotc.`number`, botbotc.unit, cot.price, cot.inservice from clinic_oral_tariff cot left join ( select bot.id as oralTariffId, botc.id as oralTariffCategoryId, botc.`name` as oralTariffCategoryName, botc.number as oralTariffCategoryNumber, bot.item_number as number, bot.`name`, bot.pinyin, bot.english_name as englishName, bot.unit from base_oral_tariff bot left join base_oral_tariff_category botc on bot.oral_tariff_category_id = botc.id ) botbotc on cot.oral_tariff_id = botbotc.oralTariffId ) cot
and cot.orgId = #{queryForm.orgId}
and cot.oralTariffCategoryId = #{queryForm.oralTariffCategoryId}
and cot.oralTariffId = #{queryForm.oralTariffId}
and CONCAT(IFNULL( cot.name, '' ), IFNULL( cot.pinyin, '' ), IFNULL( cot.number, '' )) like concat('%', #{queryForm.keyWord}, '%')
and cot.inservice = #{queryForm.inservice}
